<?php $u=rtrim($_ENV['APP_URL']??'','/'); use App\Core\Csrf; ?>
<?php if(!empty($flash)):?><section class="card"><strong><?=htmlspecialchars($flash['type']==='error'?'No se pudo completar la operación':'Operación completada')?></strong><p><?=htmlspecialchars($flash['message'])?></p></section><?php endif;?>
<?php if(!empty($businessError)):?><section class="card"><strong>No se puede generar la propuesta</strong><p><?=htmlspecialchars($businessError)?></p><p><a href="<?=$u?>/admin/academico/matriculas/propuesta?trayectoria_id=<?=$trajectory['id']?>">Volver a seleccionar oferta</a></p></section><?php endif;?>
<div class="page-head"><div><span class="eyebrow">MOTOR DE MATRÍCULA</span><h1>Propuesta académica</h1><p><strong><?=htmlspecialchars($trajectory['estudiante'])?></strong> · <?=htmlspecialchars($trajectory['carrera'])?> · <?=htmlspecialchars($trajectory['malla_codigo'].' '.$trajectory['malla'])?></p></div></div>
<section class="card"><form method="get" action="<?=$u?>/admin/academico/matriculas/propuesta" class="form-grid"><input type="hidden" name="trayectoria_id" value="<?=$trajectory['id']?>"><label style="grid-column:1/-1">Oferta académica<select name="oferta_id" required><option value="">Seleccione...</option><?php foreach($offers as $o):?><option value="<?=$o['id']?>" <?=$selectedOffer==(int)$o['id']?'selected':''?>><?=htmlspecialchars($o['periodo'].' · '.$o['nombre'].' · '.$o['estado'].' · '.$o['secciones_disponibles'].' secciones'.($o['matricula_existente']?' · YA MATRICULADO':''))?></option><?php endforeach;?></select></label><div><button class="btn">Calcular propuesta</button></div></form><?php if(!$offers):?><p>No existe una oferta compatible con carrera, malla, sede y modalidad de esta trayectoria.</p><?php endif;?></section>
<?php if(!empty($existingEnrollment)):?>
<section class="card"><strong>Ya existe una matrícula para este período</strong><p>La trayectoria ya tiene la matrícula <strong><?=htmlspecialchars($existingEnrollment['numero_matricula'])?></strong> en estado <strong><?=htmlspecialchars($existingEnrollment['estado'])?></strong>. No se puede crear un segundo borrador para el mismo período.</p><p><a class="btn" href="<?=$u?>/admin/academico/matriculas/ver?id=<?=$existingEnrollment['id']?>">Abrir matrícula existente</a></p></section>
<?php endif;?>
<?php if($proposal):?>
<div class="stats-grid"><div class="stat-card"><span>Asignaturas malla</span><strong><?=count($proposal['subjects'])?></strong></div><div class="stat-card"><span>Elegibles</span><strong><?=count(array_filter($proposal['subjects'],fn($x)=>$x['eligible']))?></strong></div><div class="stat-card"><span>Ya aprobadas</span><strong><?=count(array_filter($proposal['subjects'],fn($x)=>$x['approved']!==null))?></strong></div><div class="stat-card"><span>Bloqueadas</span><strong><?=count(array_filter($proposal['subjects'],fn($x)=>!$x['eligible']&&$x['approved']===null))?></strong></div></div>
<form method="post" action="<?=$u?>/admin/academico/matriculas/crear"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="trayectoria_id" value="<?=$trajectory['id']?>"><input type="hidden" name="oferta_id" value="<?=$selectedOffer?>">
<section class="card"><div class="section-head"><div><span class="eyebrow">PROPUESTA</span><h2><?=htmlspecialchars($proposal['offer']['periodo'])?></h2></div></div><div class="table-scroll"><table><thead><tr><th>Nivel</th><th>Asignatura</th><th>Historial</th><th>Prerrequisitos AND</th><th>Resultado</th><th>Sección</th></tr></thead><tbody><?php foreach($proposal['subjects'] as $x):?><tr><td><?=htmlspecialchars($x['nivel'])?></td><td><strong><?=htmlspecialchars($x['codigo'].' · '.$x['nombre'])?></strong><br><small><?=$x['creditos']?> créditos</small></td><td><?php if($x['approved']):?><span class="badge success">Aprobada / reconocida</span><br><small><?=htmlspecialchars($x['approved']['detail'])?></small><?php else:?>Intentos previos: <?=$x['attempt']['max']?><br><small>Siguiente: <?=$x['attempt']['next']?><?=$x['pending']?' · pendiente':''?></small><?php endif;?></td><td><?php if(!$x['prerequisites']):?>Sin prerrequisitos<?php else:?><?php foreach($x['prerequisites'] as $pr):?><div><span class="badge <?=$pr['cumplido']?'success':'muted'?>"><?=$pr['cumplido']?'✓':'✕'?></span> <?=htmlspecialchars($pr['codigo'].' '.$pr['nombre'])?></div><?php endforeach;?><?php endif;?></td><td><?php if($x['eligible']):?><span class="badge success">ELEGIBLE</span><?php else:?><span class="badge muted">NO PROPUESTA</span><br><small><?=htmlspecialchars($x['reason'])?></small><?php endif;?></td><td><?php if($x['eligible']):?><select name="seccion[<?=$x['malla_asignatura_id']?>]"><option value="">No incluir</option><?php $first=true; foreach($x['sections'] as $s):?><option value="<?=$s['id']?>" <?=$s['available']?'':'disabled'?> <?=$s['available']&&$first?'selected':''?>><?php if($s['available']&&$first)$first=false;?><?=htmlspecialchars($s['codigo'].' · '.($s['paralelo']?:$s['nombre']).' · '.($s['cupo_maximo']===null?'sin límite':($s['ocupados'].'/'.$s['cupo_maximo'])))?></option><?php endforeach;?></select><?php foreach($x['sections'] as $s): if(!$s['available']):?><div><a href="<?=$u?>/admin/academico/cupos/solicitar?seccion_id=<?=$s['id']?>">Cupo completo · Solicitar ampliación (<?=htmlspecialchars($s['codigo'])?>)</a></div><?php endif; endforeach;?><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><p><small>Orion exige TODOS los prerrequisitos. Las asignaturas aprobadas/reconocidas no se vuelven a proponer. Un cuarto intento nunca es permitido.</small></p><button class="btn">Guardar borrador de matrícula</button></section></form>
<?php endif;?>
